4	import { importModule } from '../../esm';
5	import logger from '../../logger';
6	import { runPython } from '../../python/pythonUtils';
7	import { isJavascriptFile, JAVASCRIPT_EXTENSIONS } from '../fileExtensions';
8	
9	export const functionCache: Record<string, Function> = {};
10	
11	interface LoadFunctionOptions {
12	  filePath: string;
13	  functionName?: string;
14	  defaultFunctionName?: string;
15	  basePath?: string;
16	  useCache?: boolean;
17	}
