/**
 * Extracts the file path and function name from a file:// URL
 * @param fileUrl The file:// URL (e.g., "file://path/to/file.js:functionName")
 * @returns The file path and optional function name
 *
 * A colon is only treated as a function-name separator when the portion of the path
 * before the last colon resolves to a JavaScript/TypeScript or Python file. This keeps
 * colons that appear in Windows drive letters (e.g. `C:/...`), directory names, or file
 * names from being mistaken for a function separator.
 *
 * On Windows (win32) a leading slash before a drive letter (e.g. `/C:/...`, produced by
 * the canonical `file:///C:/...` form) is stripped. On POSIX platforms the path is
 * returned as-is so that leading slashes on absolute paths are preserved.
 */
export function parseFileUrl(fileUrl: string): { filePath: string; functionName?: string } {
  if (!fileUrl.startsWith('file://')) {
    throw new Error('URL must start with file://');
  }

  const urlWithoutProtocol = fileUrl.slice('file://'.length);

  let filePath = urlWithoutProtocol;
  let functionName: string | undefined;

  const lastColonIndex = urlWithoutProtocol.lastIndexOf(':');
  if (lastColonIndex > 1) {
    const pathBeforeColon = urlWithoutProtocol.slice(0, lastColonIndex);
    if (isFunctionContainerFile(pathBeforeColon)) {
      filePath = pathBeforeColon;
      functionName = urlWithoutProtocol.slice(lastColonIndex + 1);
    }
  }

  // On Windows, canonical file URLs take the form `file:///C:/path`, leaving a leading
  // slash before the drive letter after the protocol is stripped. Remove it so the path
  // resolves correctly. POSIX paths keep their leading slash.
  if (process.platform === 'win32' && /^\/[A-Za-z]:\//.test(filePath)) {
    filePath = filePath.slice(1);
  }

  return functionName === undefined ? { filePath } : { filePath, functionName };
