  const lastColonIndex = urlWithoutProtocol.lastIndexOf(':');

  if (lastColonIndex > 1) {
    return {
      filePath: urlWithoutProtocol.slice(0, lastColonIndex),
      functionName: urlWithoutProtocol.slice(lastColonIndex + 1),
    };
  }

  return {
    filePath: urlWithoutProtocol,
  };
